import java.lang.reflect.Field;
import java.lang.reflect.Method;
import net.minecraft.SharedConstants;
import net.minecraft.core.BlockPos;
import net.minecraft.resources.Identifier;
import net.minecraft.server.Bootstrap;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.levelgen.Aquifer;
import net.minecraft.world.level.levelgen.LegacyRandomSource;
import net.minecraft.world.level.levelgen.XoroshiroRandomSource;
import net.minecraft.world.level.levelgen.densityfunction.*;

// Read the centers generated by the real 26.3 noise-based aquifer.
public class AquiferCentersOracle {
    public static void main(String[] args) throws Exception {
        var stdout = System.out;
        SharedConstants.tryDetectVersion();
        Bootstrap.bootStrap();
        var zero = DensityFunctions.zero();
        var config = new Aquifer.Config(zero, zero, zero, zero, zero, DensityFunctions.constant(256));
        var compiler = new DensityFunctionCompiler(null);
        DensitySamplerSet samplers = f -> new DensitySampler.Bound(compiler.getSampler(f), SamplerContext.EMPTY_UNCACHED);
        var klass = Class.forName("net.minecraft.world.level.levelgen.Aquifer$NoiseBasedAquifer");
        Field cacheField = klass.getDeclaredField("aquiferLocationCache");
        cacheField.setAccessible(true);
        Method index = klass.getDeclaredMethod("getIndex", int.class, int.class, int.class);
        index.setAccessible(true);
        int[][] chunks = {{-32, 48}, {12336, -9840}, {-30000000, 29999984}};
        for (int mode = 0; mode < 2; mode++) for (long seed : new long[]{0, -1, 2345, Long.MIN_VALUE, Long.MAX_VALUE}) {
            RandomSource random = mode == 0 ? new LegacyRandomSource(seed) : new XoroshiroRandomSource(seed);
            var factory = random.forkPositional().fromHashOf(Identifier.withDefaultNamespace("aquifer")).forkPositional();
            stdout.printf("S %d %d%n", mode, seed);
            for (int[] chunk : chunks) {
                var volume = new DensityVolume(16, 128, 16, chunk[0], -64, chunk[1]);
                Aquifer aquifer = config.create(samplers, factory, volume,
                    (x, y, z) -> new Aquifer.FluidStatus(63, Blocks.WATER.defaultBlockState()));
                for (int n = 0; n < 64; n++) {
                    int x = chunk[0] + (n * 7 % 16), y = -64 + (n * 37 % 128), z = chunk[1] + (n * 11 % 16);
                    aquifer.computeSubstance(x, y, z, -1.0);
                    long[] cache = (long[])cacheField.get(aquifer);
                    int bx = (x - 5) >> 4, by = Math.floorDiv(y + 1, 12), bz = (z - 5) >> 4;
                    int[] best = {-1, -1, -1, -1}, distances = {Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE};
                    StringBuilder out = new StringBuilder("P " + x + " " + y + " " + z);
                    int candidate = 0;
                    for (int dx = 0; dx <= 1; dx++) for (int dy = -1; dy <= 1; dy++) for (int dz = 0; dz <= 1; dz++) {
                        int i = (int)index.invoke(aquifer, bx + dx, by + dy, bz + dz);
                        long pos = cache[i];
                        if (pos == Long.MAX_VALUE) throw new AssertionError("center was not generated");
                        int cx = BlockPos.getX(pos), cy = BlockPos.getY(pos), cz = BlockPos.getZ(pos);
                        out.append(' ').append(cx).append(' ').append(cy).append(' ').append(cz);
                        int a = cx - x, b = cy - y, c = cz - z, distance = a*a + b*b + c*c;
                        for (int j = 0; j < 4; j++) if (distance <= distances[j]) {
                            for (int k = 3; k > j; k--) { best[k] = best[k-1]; distances[k] = distances[k-1]; }
                            best[j] = candidate; distances[j] = distance; break;
                        }
                        candidate++;
                    }
                    for (int value : best) out.append(' ').append(value);
                    stdout.println(out);
                }
            }
        }
    }
}
